using Autodesk.Revit.DB;
var doc = Document;
// Goal: create a NEW area scheme by cloning an existing one. AreaScheme has no Create and no
// Duplicate; it is copied. Reads at top level, the copy + rename in one WithTransaction block.

// 1. Pick the source scheme to clone. The clone INHERITS IsGrossBuildingArea from its source and
//    that flag is read-only, so choose by the kind you want: the Gross Building scheme for a gross
//    plan, otherwise a Rentable/BOMA scheme. Here: prefer the gross one, else the first scheme.
AreaScheme source = null, firstScheme = null;
foreach (AreaScheme s in new FilteredElementCollector(doc).OfClass(typeof(AreaScheme))) {
  if (firstScheme == null) firstScheme = s;
  if (s.IsGrossBuildingArea) { source = s; break; }
}
if (source == null) source = firstScheme;
if (source == null) throw new System.Exception("no AreaScheme to clone in this document");

// 2. A unique name: setting AreaScheme.Name to one already in use throws. Collect existing names.
var existing = new System.Collections.Generic.HashSet<string>();
foreach (AreaScheme s in new FilteredElementCollector(doc).OfClass(typeof(AreaScheme))) existing.Add(s.Name);
string wanted = "Custom Area Scheme";
string newName = wanted;
int n = 1;
while (existing.Contains(newName)) { n++; newName = wanted + " " + n; }

return Connector.WithTransaction(doc, () => {
  // 3. Clone it. AreaScheme derives from Element (NOT ElementType), so ElementType.Duplicate(name)
  //    does not exist on it and there is no AreaScheme.Create. ElementTransformUtils.CopyElement
  //    copies the scheme element; the translation is irrelevant (a scheme has no geometry), so pass
  //    XYZ.Zero. It returns a collection of new ids; the new AreaScheme is the one among them.
  var copied = ElementTransformUtils.CopyElement(doc, source.Id, XYZ.Zero);
  AreaScheme created = null;
  foreach (var id in copied) { var e = doc.GetElement(id) as AreaScheme; if (e != null) { created = e; break; } }
  if (created == null) throw new System.Exception("copy produced no AreaScheme");

  // 4. Rename the clone (Revit names it "<source> 1"); the name must be unique among area schemes.
  created.Name = newName;
  doc.Regenerate();

  return new {
    sourceName = source.Name, sourceGross = source.IsGrossBuildingArea,
    createdId = created.Id.Value, createdName = created.Name,
    createdGross = created.IsGrossBuildingArea,
    grossInheritedFromSource = created.IsGrossBuildingArea == source.IsGrossBuildingArea
  };
});
